import torch


def run_correctness(input, output_size, align_corners):
    output = torch.ops.aten._upsample_bilinear2d_aa(
        input.float(),
        output_size=output_size,
        align_corners=align_corners,
    )
    return output.to(input.dtype)


def run(input, output_size, align_corners):
    return torch.ops.aten._upsample_bilinear2d_aa(
        input,
        output_size=output_size,
        align_corners=align_corners,
    )
